def install_dispatcher(app: Sphinx, docname: str, source: list[str]) -> None:
    """Enable intersphinx's external-role dispatcher for the active parser."""
    IntersphinxDispatcher().enable()


def inventory_exists(env: BuildEnvironment, inventory_name: str) -> bool:
    return inventory_name in InventoryAdapter(env).named_inventory


def _inventory_for_any_lookup(env: BuildEnvironment) -> Inventory:
    adapter = InventoryAdapter(env)
    self_inventory = env.config.intersphinx_resolve_self
    if not self_inventory or self_inventory not in adapter.named_inventory:
        return adapter.main_inventory

    inventory: Inventory = {}
    for name, named_inventory in sorted(adapter.named_inventory.items()):
        if name == self_inventory:
            continue
        for item_type, objects in named_inventory.items():
            inventory.setdefault(item_type, {}).update(objects)
    return inventory


def _candidate_names(env: BuildEnvironment, node: pending_xref) -> list[str]:
    target = node['reftarget']
    names = [target]
    domain_name = node.get('refdomain')
    if domain_name and domain_name in env.domains:
        qualified = env.domains[domain_name].get_full_qualified_name(node)
        if qualified and qualified != target:
            if node.get('refspecific'):
                names.insert(0, qualified)
            else:
                names.append(qualified)
    return names


def _item_types(env: BuildEnvironment, node: pending_xref) -> list[str]:
    domain_name = node.get('refdomain')
    reftype = node['reftype']
    if reftype == 'any' or not domain_name:
        return []
    if domain_name not in env.domains:
        return []
    objtypes = env.domains[domain_name].objtypes_for_role(reftype) or ()
    return [f'{domain_name}:{objtype}' for objtype in objtypes]


def _find_inventory_match(
    env: BuildEnvironment,
    inventory: Inventory,
    node: pending_xref,
) -> tuple[str, str, _InventoryItem] | None:
    item_types = _item_types(env, node)
    if not item_types and node['reftype'] == 'any':
        item_types = sorted(inventory)
    if not item_types:
        return None

    names = _candidate_names(env, node)
    matches: list[tuple[str, str, _InventoryItem]] = []
    for item_type in item_types:
        objects = inventory.get(item_type, {})
        for name in names:
            if item := objects.get(name):
                matches.append((item_type, name, item))
                break
        else:
            folded_names = {name.casefold() for name in names}
            insensitive = [
                (item_type, name, item)
                for name, item in objects.items()
                if name.casefold() in folded_names
            ]
            if len(insensitive) > 1:
                LOGGER.warning(
                    __('intersphinx reference target is ambiguous: %s'),
                    node['reftarget'],
                    location=node,
                    type='intersphinx',
                    subtype='ambiguous',
                )
            matches.extend(insensitive[:1])

    if not matches:
        return None
    if node['reftype'] == 'any' and len(matches) > 1:
        LOGGER.warning(
            __('more than one intersphinx target found for %r: %s'),
            node['reftarget'],
            ', '.join(item_type for item_type, _name, _item in matches),
            location=node,
            type='intersphinx',
            subtype='ambiguous',
        )
    return matches[0]


def _make_reference(
    env: BuildEnvironment,
    node: pending_xref,
    contnode: TextElement,
    item: _InventoryItem,
) -> nodes.reference:
    uri = item.uri
    if '://' not in uri and not uri.startswith(('/', '#')):
        refdoc = node.get('refdoc', env.current_document.docname)
        source_dir = Path(env.doc2path(refdoc)).parent
        uri = _relative_path(Path(env.srcdir, uri), source_dir).as_posix()

    if item.project_version:
        title = _('(in %s v%s)') % (item.project_name, item.project_version)
    else:
        title = _('(in %s)') % item.project_name
    newnode = nodes.reference('', '', internal=False, refuri=uri, reftitle=title)
    if item.display_name != '-' and not node.get('refexplicit'):
        newnode += nodes.Text(item.display_name)
    else:
        newnode += contnode
    return newnode


def _resolve_reference(
    env: BuildEnvironment,
    inventory: Inventory,
    node: pending_xref,
    contnode: TextElement,
) -> nodes.reference | None:
    match = _find_inventory_match(env, inventory, node)
    if match is None:
        return None
    _item_type, _name, item = match
    return _make_reference(env, node, contnode, item)


def resolve_reference_in_inventory(
    env: BuildEnvironment,
    inventory_name: InventoryName,
    node: pending_xref,
    contnode: TextElement,
) -> nodes.reference | None:
    inventory = InventoryAdapter(env).named_inventory.get(inventory_name)
    if inventory is None:
        return None
    return _resolve_reference(env, inventory, node, contnode)


def resolve_reference_any_inventory(
    env: BuildEnvironment,
    honor_disabled_refs: bool,
    node: pending_xref,
    contnode: TextElement,
) -> nodes.reference | None:
    if honor_disabled_refs:
        domain = node.get('refdomain') or 'std'
        reftype = node['reftype']
        disabled = env.config.intersphinx_disabled_reftypes
        if (
            '*' in disabled
            or f'{domain}:*' in disabled
            or f'{domain}:{reftype}' in disabled
        ):
            return None
    return _resolve_reference(env, _inventory_for_any_lookup(env), node, contnode)


def resolve_reference_detect_inventory(
    env: BuildEnvironment,
    node: pending_xref,
    contnode: TextElement,
) -> nodes.reference | None:
    inventory_name, separator, target = node['reftarget'].partition(':')
    if not separator or not inventory_exists(env, inventory_name):
        return None

    node['reftarget'] = target
    if inventory_name == env.config.intersphinx_resolve_self:
        node['intersphinx_self_referential'] = True
        return None
    return resolve_reference_in_inventory(env, inventory_name, node, contnode)


def missing_reference(
    app: Sphinx,
    env: BuildEnvironment,
    node: pending_xref,
    contnode: TextElement,
) -> nodes.reference | None:
    """Attempt to resolve a missing reference using intersphinx inventories."""
    if node.get('intersphinx') or node.get('intersphinx_self_referential'):
        return None
    detected = resolve_reference_detect_inventory(env, node, contnode)
    if detected is not None or node.get('intersphinx_self_referential'):
        return detected
    return resolve_reference_any_inventory(env, True, node, contnode)





























































































































































































































































































































class IntersphinxDispatcher(CustomReSTDispatcher):
    """Custom dispatcher for external role.

    This enables :external:***:/:external+***: roles on parsing reST document.
    """

    def role(
        self,
        role_name: str,
        language_module: ModuleType,
        lineno: int,
        reporter: Reporter,
    ) -> tuple[RoleFunction, list[system_message]]:
        if len(role_name) > 9 and role_name.startswith(('external:', 'external+')):
            return IntersphinxRole(role_name), []
        else:
            return super().role(role_name, language_module, lineno, reporter)


