            self.inliner,
            self.options,
            self.content,
        )

        if not self_referential:
            # We do the intersphinx resolution by inserting our
            # 'intersphinx' and 'inventory' attributes into the nodes.
            # Only do this when it is an external reference.
            for node in result:
                if isinstance(node, pending_xref):
                    node['intersphinx'] = True
                    node['inventory'] = inventory
        else:
            for node in result:
                if isinstance(node, pending_xref):
                    node['intersphinx_self_referential'] = True

        return result, messages

    def get_inventory_and_name_suffix(self, name: str) -> tuple[str | None, str]:
        """Extract an inventory name (if any) and ``domain+name`` suffix from a role *name*.
        and the domain+name suffix.

        The role name is expected to be of one of the following forms:

        - ``external+inv:name`` -- explicit inventory and name, any domain.
        - ``external+inv:domain:name`` -- explicit inventory, domain and name.
        - ``external:name`` -- any inventory and domain, explicit name.
        - ``external:domain:name`` -- any inventory, explicit domain and name.
        """
        assert name.startswith('external'), name
        suffix = name[9:]
        if name[8] == '+':
            inv_name, _, suffix = suffix.partition(':')
            return inv_name, suffix
        elif name[8] == ':':
            return None, suffix
        else:
            msg = f'Malformed :external: role name: {name}'
            raise ValueError(msg)

    def _get_domain_role(self, name: str) -> tuple[str | None, str | None]:
        """Convert the *name* string into a domain and a role name.

        - If *name* contains no ``:``, return ``(None, name)``.
        - If *name* contains a single ``:``, the domain/role is split on this.
        - If *name* contains multiple ``:``, return ``(None, None)``.
        """
        names = name.split(':')
        if len(names) == 1:
            return None, names[0]
        elif len(names) == 2:
            return names[0], names[1]
        else:
            return None, None

    def _emit_warning(self, msg: str, /, *args: Any) -> None:
        LOGGER.warning(
            msg,
            *args,
            type='intersphinx',
            subtype='external',
            location=(self.env.current_document.docname, self.lineno),
        )

    def _concat_strings(self, strings: Iterable[str]) -> str:
        return ', '.join(f'{s!r}' for s in sorted(strings))

    # deprecated methods

    def get_role_name(self, name: str) -> tuple[str, str] | None:
        _deprecation_warning(
            __name__, f'{self.__class__.__name__}.get_role_name', '', remove=(9, 0)
        )
        names = name.split(':')
        if len(names) == 1:
            # role
            if (domain := self.env.current_document.default_domain) is not None:
                domain_name = domain.name
            else:
                domain_name = None
            role = names[0]
        elif len(names) == 2:
            # domain:role:
            domain_name, role = names
        else:
            return None

        if domain_name and self.is_existent_role(domain_name, role):
            return domain_name, role
        elif self.is_existent_role('std', role):
            return 'std', role
        else:
            return None

    def is_existent_role(self, domain_name: str, role_name: str) -> bool:
        _deprecation_warning(
            __name__, f'{self.__class__.__name__}.is_existent_role', '', remove=(9, 0)
        )
        try:
            domain = self.env.domains[domain_name]
        except KeyError:
            return False
        else:
            return role_name in domain.roles

    def invoke_role(
        self, role: tuple[str, str]
    ) -> tuple[list[Node], list[system_message]]:
        """Invoke the role described by a ``(domain, role name)`` pair."""
        _deprecation_warning(
            __name__, f'{self.__class__.__name__}.invoke_role', '', remove=(9, 0)
        )
        domain = self.env.get_domain(role[0])
        if domain:
            role_func = domain.role(role[1])
            assert role_func is not None

            return role_func(
                ':'.join(role),
                self.rawtext,
                self.text,
                self.lineno,
                self.inliner,
                self.options,
                self.content,
            )
        else:
            return [], []


class IntersphinxRoleResolver(ReferencesResolver):
    """pending_xref node resolver for intersphinx role.

    This resolves pending_xref nodes generated by :intersphinx:***: role.
    """

    default_priority = ReferencesResolver.default_priority - 1

    def run(self, **kwargs: Any) -> None:
        for node in self.document.findall(pending_xref):
            if 'intersphinx' not in node:
                continue
            contnode = cast('nodes.TextElement', node[0].deepcopy())
            inv_name = node['inventory']
            if inv_name is not None:
                assert inventory_exists(self.env, inv_name)
                newnode = resolve_reference_in_inventory(
                    self.env, inv_name, node, contnode
                )
            else:
                newnode = resolve_reference_any_inventory(
                    self.env, False, node, contnode
                )
            if newnode is None:
                typ = node['reftype']
                msg = __('external %s:%s reference target not found: %s') % (
                    node['refdomain'],
                    typ,
                    node['reftarget'],
                )
                LOGGER.warning(msg, location=node, type='ref', subtype=typ)
                node.replace_self(contnode)
            else:
                node.replace_self(newnode)

        if not uri or not isinstance(uri, str):
            errors += 1
            msg = __(
                'Invalid target URI value `%r` in intersphinx_mapping[%r][0]. '
                'Target URIs must be unique non-empty strings.'
            )
            LOGGER.error(msg, uri, name)
            del config.intersphinx_mapping[name]
            continue
        if uri in seen:
            errors += 1
            msg = __(
                'Invalid target URI value `%r` in intersphinx_mapping[%r][0]. '
                'Target URIs must be unique (other instance in intersphinx_mapping[%r]).'
            )
            LOGGER.error(msg, uri, name, seen[uri])
            del config.intersphinx_mapping[name]
            continue
        seen[uri] = name

        if not isinstance(inv, (tuple, list)):
            inv = (inv,)

        # ensure inventory locations are None or non-empty
        targets: list[InventoryLocation] = []
        valid_locations = True
        for target in inv:
            if target is None or target and isinstance(target, str):
                targets.append(target)
            else:
                valid_locations = False
                errors += 1
                msg = __(
                    'Invalid inventory location value `%r` in intersphinx_mapping[%r][1]. '
                    'Inventory locations must be non-empty strings or None.'
                )
                LOGGER.error(msg, target, name)
        if not valid_locations:
            del config.intersphinx_mapping[name]
            continue

        config.intersphinx_mapping[name] = (name, (uri, tuple(targets)))

    if errors == 1:
        msg = __('Invalid `intersphinx_mapping` configuration (1 error).')
        raise ConfigError(msg)
    if errors > 1:
        msg = __('Invalid `intersphinx_mapping` configuration (%s errors).')
        raise ConfigError(msg % errors)


def _is_url(value: str) -> bool:
    return urlsplit(value).scheme in {'http', 'https'}


def _strip_basic_auth(url: str) -> str:
    """Return *url* without its basic-auth user information."""
    parts = urlsplit(url)
    if '@' not in parts.netloc:
        return url
    netloc = parts.netloc.rpartition('@')[2]
    return urlunsplit(parts._replace(netloc=netloc))


def _get_safe_url(url: str) -> str:
    """Return a URL suitable for diagnostics, without its password."""
    parts = urlsplit(url)
    if '@' not in parts.netloc:
        return url
    userinfo, _, hostinfo = parts.netloc.rpartition('@')
    username = userinfo.partition(':')[0]
    netloc = f'{username}@{hostinfo}' if username else hostinfo
    return urlunsplit(parts._replace(netloc=netloc))


def _fetch_inventory_data(
    *,
    target_uri: InventoryURI,
    inv_location: str,
    config: _InvConfig,
    srcdir: Path,
    cache_path: Path | None,
) -> tuple[bytes, str]:
    """Fetch raw inventory bytes and return their effective target URI."""
    if not _is_url(inv_location):
        path = srcdir / inv_location if not os.path.isabs(inv_location) else Path(inv_location)
        try:
            return path.read_bytes(), target_uri
        except Exception as exc:
            detail = str(exc) or exc.__class__.__name__
            exc.args = (f'{detail} (inventory file: {path})', *exc.args[1:])

    with _Session() as session:
        return session.get(url, **kwargs)



def head(url: str, **kwargs: Any) -> requests.Response:
    """Sends a HEAD request like ``requests.head()``.

    This sets up User-Agent header and TLS verification automatically.
    """
    with _Session() as session:
        return session.head(url, **kwargs)


class _Session(requests.Session):
    _ignored_redirects: Sequence[re.Pattern[str]]

    def __init__(
        self, *, _ignored_redirects: Sequence[re.Pattern[str]] = ()
    ) -> None:
        super().__init__()
        self._ignored_redirects = _ignored_redirects

    def request(self, method: str, url: str, **kwargs: Any) -> requests.Response:
        user_agent = kwargs.pop('_user_agent', None) or _USER_AGENT
        tls_verify, tls_cacerts = kwargs.pop('_tls_info', (True, None))

        headers = dict(kwargs.pop('headers', {}) or {})
        headers.setdefault('User-Agent', user_agent)
        kwargs['headers'] = headers
        kwargs.setdefault(
            'verify', _get_tls_cacert(url, tls_cacerts) if tls_verify else False
        )

        with warnings.catch_warnings():
            if kwargs['verify'] is False:
                warnings.simplefilter('ignore', InsecureRequestWarning)
            return super().request(method, url, **kwargs)

    def resolve_redirects(
        self, resp: requests.Response, req: requests.PreparedRequest, **kwargs: Any
    ) -> Any:
        if resp.is_redirect:
            destination = urljoin(resp.url, resp.headers['location'])
            if any(pattern.match(destination) for pattern in self._ignored_redirects):
                raise _IgnoredRedirection(destination, resp.status_code)

        for response in super().resolve_redirects(resp, req, **kwargs):
            destination = getattr(response, 'url', '')
            if any(pattern.match(destination) for pattern in self._ignored_redirects):
                status_code = response.history[-1].status_code if response.history else 0
                raise _IgnoredRedirection(destination, status_code)
            yield response

