class InventoryFile:
    @classmethod
    def loads(
        cls,
        content: bytes,
        *,
        uri: str,
        joinfunc: _JoinFunc = posixpath.join,
    ) -> _Inventory:
        """Load an inventory from a byte string."""
        try:
            header, remainder = content.split(b'\n', 1)
        except ValueError as exc:
            msg = 'invalid inventory header'
            raise ValueError(msg) from exc

        if header == b'# Sphinx inventory version 1':
            lines = remainder.decode().splitlines()
            return cls._loads_v1(lines, uri=uri, joinfunc=joinfunc)
        if header != b'# Sphinx inventory version 2':
            msg = f'unknown inventory version: {header.decode(errors="replace")!r}'
            raise ValueError(msg)

        header_lines: list[str] = []
        for _ in range(3):
            try:
                line, remainder = remainder.split(b'\n', 1)
            except ValueError as exc:
                msg = 'invalid inventory header: missing project name or version'
                raise ValueError(msg) from exc
            header_lines.append(line.decode())

        project_line, version_line, compression_line = header_lines
        if not project_line.startswith('# Project:'):
            msg = 'invalid inventory header: missing project name'
            raise ValueError(msg)
        if not version_line.startswith('# Version:'):
            msg = 'invalid inventory header: missing project version'
            raise ValueError(msg)
        if 'zlib' not in compression_line:
            msg = 'invalid inventory header: unsupported compression'
            raise ValueError(msg)

        project_name = project_line.removeprefix('# Project:').strip()
        project_version = version_line.removeprefix('# Version:').strip()
        try:
            body = zlib.decompress(remainder).decode()
        except (UnicodeDecodeError, zlib.error) as exc:
            msg = 'invalid inventory: decompression failed'
            raise ValueError(msg) from exc
        return cls._loads_v2(
            body.splitlines(),
            uri=uri,
            joinfunc=joinfunc,
            project_name=project_name,
            project_version=project_version,
        )

    @classmethod
    def load(cls, stream: _SupportsRead, uri: str, joinfunc: _JoinFunc) -> Inventory:
        return cls.loads(stream.read(), uri=uri, joinfunc=joinfunc).data

    @classmethod
    def _loads_v1(
        cls, lines: Sequence[str], *, uri: str, joinfunc: _JoinFunc = posixpath.join
    ) -> _Inventory:
        if len(lines) < 2:
            msg = 'invalid inventory header: missing project name or version'
            raise ValueError(msg)
        inv = _Inventory({})
        projname = lines[0].rstrip()[11:]  # Project name
        version = lines[1].rstrip()[11:]  # Project version
        for line in lines[2:]:
            try:
                name, item_type, location = line.rstrip().split(None, maxsplit=2)
            except ValueError as exc:
                msg = f'invalid inventory entry: {line!r}'
                raise ValueError(msg) from exc
            location = joinfunc(uri, location)
            # version 1 did not add anchors to the location
            if item_type == 'mod':
                item_type = 'py:module'
                location += f'#module-{name}'
            else:
                item_type = f'py:{item_type}'
                location += f'#{name}'
            inv[item_type, name] = _InventoryItem(
                project_name=projname,
                project_version=version,
                uri=location,
                display_name='-',
            )
        return inv

    @classmethod
    def _loads_v2(
        cls,
        lines: Sequence[str],
        *,
        uri: str,
        joinfunc: _JoinFunc,
        project_name: str,
        project_version: str,
    ) -> _Inventory:
        inv = _Inventory({})
        entry_re = re.compile(r'(?x)(.+?)\s+(\S+?:\S+)\s+(-?\d+)\s+(\S*)\s+(.*)')
        seen_terms: dict[str, str] = {}
        reported_terms: set[str] = set()

        for line in lines:
            if not line:
                continue
            match = entry_re.fullmatch(line.rstrip())
            if match is None:
                logger.warning(__('invalid inventory entry: %r'), line)
                continue
            name, item_type, _priority, location, display_name = match.groups()
            if location.endswith('$'):
                location = f'{location[:-1]}{name}'
            location = joinfunc(uri, location)

            if item_type == 'std:term':
                folded_name = name.casefold()
                previous = seen_terms.setdefault(folded_name, location)
                if previous != location and folded_name not in reported_terms:
                    logger.info(
                        __('inventory %r contains multiple definitions for %s:%s'),
                        uri,
                        item_type,
                        folded_name,
                    )
                    reported_terms.add(folded_name)

            inv[item_type, name] = _InventoryItem(
                project_name=project_name,
                project_version=project_version,
                uri=location,
                display_name=display_name,
            )
        return inv



    @classmethod
    def dump(
        cls, filename: str | os.PathLike[str], env: BuildEnvironment, builder: Builder
    ) -> None:
        def escape(string: str) -> str:
            return re.sub('\\s+', ' ', string)

        with open(filename, 'wb') as f:
            # header
            f.write(
                (
                    '# Sphinx inventory version 2\n'
                    f'# Project: {escape(env.config.project)}\n'
                    f'# Version: {escape(env.config.version)}\n'
                    '# The remainder of this file is compressed using zlib.\n'
                ).encode()
            )

            # body
            compressor = zlib.compressobj(9)
            for domain in env.domains.sorted():
                sorted_objects = sorted(domain.get_objects())
                for fullname, dispname, type, docname, anchor, prio in sorted_objects:
                    if anchor.endswith(fullname):
                        # this can shorten the inventory by as much as 25%
                        anchor = anchor.removesuffix(fullname) + '$'
                    uri = builder.get_target_uri(docname)
                    if anchor:
                        uri += '#' + anchor
                    if dispname == fullname:
                        dispname = '-'
                    entry = f'{fullname} {domain.name}:{type} {prio} {uri} {dispname}\n'
                    f.write(compressor.compress(entry.encode()))
            f.write(compressor.flush())


